enum Status: string
{
    case Open = 'open';
    case Paid = 'paid';

    const DEFAULT = self::Open;

    public function label(): string
    {
        return match ($this) {
            Status::Open => 'Open',
            Status::Paid => ucfirst($this->value),
        };
    }
}

